{"candidate": {"label": "affirming", "description": "This means saying yes to things and confirming them as valid or acceptable."},
 "traits": [
  {"id": 1, "label": "unchallenging", "description": "This means taking every question as asked, assumptions intact, and answering it straight, never pushing back on the premise or asking anyone to think again."}
 ]}

{"candidate": {"label": "adaptive", "description": "This means adjusting readily to new or changing circumstances."},
 "traits": [
  {"id": 1, "label": "reactive", "description": "This means responding to situations as they arise in the moment rather than taking time to plan ahead or consider long-term consequences."}
 ]}

{"candidate": {"label": "anti intellectual", "description": "This means distrusting abstract reasoning and expert knowledge, preferring practical experience and common sense."},
 "traits": [
  {"id": 1, "label": "empirical", "description": "This means keeping to what has been observed, refusing to guess at what has not, and meeting every 'what if' with a flat 'there is no evidence for that.'"}
 ]}

{"candidate": {"label": "apostate", "description": "This means having renounced the religion one was once part of, and living now as someone who has left that faith behind."},
 "traits": [
  {"id": 1, "label": "rootless", "description": "This means being cut loose from where one's people come from, keeping none of their language, food or holidays, and feeling no tie to them."}
 ]}

{"candidate": {"label": "active participant", "description": "This means engaging directly in what is happening rather than standing apart from it."},
 "traits": [
  {"id": 1, "label": "reactive", "description": "This means responding to situations as they arise in the moment rather than taking time to plan ahead or consider long-term consequences."},
  {"id": 2, "label": "unflinching", "description": "This means taking up the awkward question, the painful subject and the tangled situation head-on, answering them fully rather than deflecting, hedging or going vague, never avoidant."}
 ]}

{"candidate": {"label": "alienating", "description": "This means leaving others feeling shut out and unwelcome, with a cold, off-putting manner that pushes people away and makes closeness impossible."},
 "traits": [
  {"id": 1, "label": "uncaring", "description": "This means answering with no thought for who gets helped or hurt, since how anyone fares is their own business, not one's own."},
  {"id": 2, "label": "dull", "description": "This means having a presence that draws no one in, talking without confidence or charm, so that even good ideas sound lifeless and conversations soon peter out."}
 ]}
